package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	line := scanner.Text()

	parts := strings.Split(line, " ")
	sum := 0
	for _, part := range parts {
		num, _ := strconv.Atoi(part)
		sum += num
	}

	if sum > 0 && sum%5 == 0 {
		fmt.Println(sum / 5)
	} else {
		fmt.Println("-1")
	}
}

